// Forecast Fan — Time Series, route: jsx
// Source: original:gaps/fan-chart
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from fanChart ----
// Seeded monthly demand series: 36 months of history, then a 12-month forecast
// whose quantile bands (50/80/95, narrowest first) widen with the horizon.
// Fixed Date constructions and a mulberry32 PRNG keep every load identical.
function mulberry32(seed: number) {
  let a = seed;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const rng = mulberry32(20260118);

function randomNormal(mean: number, stdDev: number) {
  const u1 = rng();
  const u2 = rng();
  const z = Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
  return mean + z * stdDev;
}

function trend(monthIndex: number) {
  return 100 + 1.2 * monthIndex + 10 * Math.sin((2 * Math.PI * monthIndex) / 12);
}

// z-scores for the central 50/80/95% quantile intervals of a normal.
const BAND_Z = [0.674, 1.282, 1.96];

const demandForecast: {
  history: { date: Date; value: number }[];
  forecast: { date: Date; mid: number; bands: [number, number][] }[];
} = {
  history: Array.from({ length: 36 }, (_, i) => ({
    date: new Date(2023, i, 1),
    value: Math.round(trend(i) + randomNormal(0, 4))
  })),
  forecast: Array.from({ length: 12 }, (_, h) => {
    const mid = trend(36 + h);
    const sd = 4 * Math.sqrt(h + 1);
    return {
      date: new Date(2026, h, 1),
      mid: Math.round(mid),
      bands: BAND_Z.map((z) => [Math.round(mid - z * sd), Math.round(mid + z * sd)] as [number, number])
    };
  })
};

const MARGIN = { top: 16, right: 40, bottom: 36, left: 46 };

// Band fill opacity by band index, narrowest first: narrow bands paint last and darkest.
const OPACITY = [0.45, 0.28, 0.16];

/**
 * History as observed values, then a forecast median with nested quantile
 * intervals. `bands` is ordered narrowest to widest (e.g. 50/80/95%).
 */
export type Data = {
  history: { date: Date; value: number }[];
  forecast: { date: Date; mid: number; bands: [number, number][] }[];
};

export default function FanChart({ data = demandForecast, width }: { data?: Data; width: number }) {
  const height = Math.round(width * 0.55);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  // The fan opens from the last observed point, so anchor a zero-width band there.
  const forecast = useMemo(() => {
    const last = data.history[data.history.length - 1];
    const anchor = {
      date: last.date,
      mid: last.value,
      bands: data.forecast[0].bands.map(() => [last.value, last.value] as [number, number])
    };
    return [anchor, ...data.forecast];
  }, [data]);

  const x = useMemo(
    () =>
      d3
        .scaleUtc()
        .domain([data.history[0].date, data.forecast[data.forecast.length - 1].date])
        .range([0, innerWidth]),
    [data, innerWidth]
  );

  const y = useMemo(() => {
    const lows = forecast.flatMap((d) => d.bands.map((b) => b[0]));
    const highs = forecast.flatMap((d) => d.bands.map((b) => b[1]));
    return d3
      .scaleLinear()
      .domain([
        Math.min(d3.min(data.history, (d) => d.value) ?? 0, d3.min(lows) ?? 0),
        Math.max(d3.max(data.history, (d) => d.value) ?? 1, d3.max(highs) ?? 1)
      ])
      .nice()
      .range([innerHeight, 0]);
  }, [data, forecast, innerHeight]);

  const historyPath = useMemo(
    () =>
      d3
        .line<Data['history'][number]>()
        .x((d) => x(d.date))
        .y((d) => y(d.value))(data.history) ?? '',
    [data, x, y]
  );

  const midPath = useMemo(
    () =>
      d3
        .line<(typeof forecast)[number]>()
        .x((d) => x(d.date))
        .y((d) => y(d.mid))(forecast) ?? '',
    [forecast, x, y]
  );

  const bandPaths = useMemo(() => {
    const bandCount = forecast[0].bands.length;
    return Array.from({ length: bandCount }, (_, i) =>
      d3
        .area<(typeof forecast)[number]>()
        .x((d) => x(d.date))
        .y0((d) => y(d.bands[i][0]))
        .y1((d) => y(d.bands[i][1]))(forecast) ?? ''
    );
  }, [forecast, x, y]);

  const bandLabels = forecast[0].bands.length === 3 ? ['50%', '80%', '95%'] : [];
  const lastForecast = data.forecast[data.forecast.length - 1];

  const xTicks: Tick[] = useMemo(
    () =>
      x.ticks(Math.min(8, Math.max(2, Math.round(innerWidth / 130)))).map((v) => ({
        value: d3.utcFormat('%b %Y')(v),
        offset: x(v)
      })),
    [x, innerWidth]
  );

  const yTicks: Tick[] = useMemo(
    () => y.ticks(6).map((v) => ({ value: String(v), offset: y(v) })),
    [y]
  );

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Monthly history line followed by a forecast median with nested 50, 80 and 95 percent quantile bands widening into the future"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        <line
          x1={x(data.history[data.history.length - 1].date)}
          x2={x(data.history[data.history.length - 1].date)}
          y1={0}
          y2={innerHeight}
          stroke="var(--muted)"
          strokeDasharray="3 3"
        />
        {/* Widest band first, so the narrow bands paint on top. */}
        {[...bandPaths.keys()].reverse().map((i) => (
          <path key={i} d={bandPaths[i]} fill="var(--accent)" fillOpacity={OPACITY[i] ?? 0.1} />
        ))}
        <path d={historyPath} fill="none" stroke="var(--text)" strokeWidth={1.5} />
        <path d={midPath} fill="none" stroke="var(--accent)" strokeWidth={2} strokeDasharray="5 3" />
        {bandLabels.map((label, i) => (
          <text
            key={label}
            x={innerWidth + 4}
            y={y(lastForecast.bands[i][1])}
            dy="0.32em"
            fontSize={10}
            fill="var(--muted)"
          >
            {label}
          </text>
        ))}
      </g>
    </svg>
  );
}
